-- ExamGrind verified recovery desk: 5 November 2026.
-- Primary-source-checked releases from 3-4 November 2026.

insert into public.current_affairs_briefs (slug, published_on, title, summary, why_it_matters, background, source_title, source_url, source_publisher, source_published_on, prelims_takeaways, quick_check, visual_data, status, reviewed_at) values
(
$$2026-11-05-ftsc-continuation$$, $$2026-11-05$$,
$$Cabinet extends Fast Track Special Courts scheme through March 2031$$,
$$The Union Cabinet approved a five-year continuation of the Centrally Sponsored Scheme for Fast Track Special Courts, including exclusive POCSO Courts. The extension runs from 1 April 2026 to 31 March 2031 and carries a total outlay of Rs 3,788.04 crore.$$,
$$This is a high-value polity and social-justice update: it connects the POCSO Act, the Nirbhaya Fund, Centre-State scheme financing and judicial capacity for sexual-offence cases.$$,
$$FTSCs are dedicated courts for faster disposal of specified rape and POCSO cases; they are not identical to every fast-track court. The approved plan provides for up to 850 FTSCs, compared with 779 then functional, and the Department of Justice will coordinate implementation with States and Union Territories.$$,
$$Cabinet approves continuation of the Centrally Sponsored Scheme for Fast Track Special Courts$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332483$$,
$$Department of Justice / Press Information Bureau$$, $$2026-11-04$$,
$$["The continuation period is 1 April 2026 to 31 March 2031.","The scheme includes exclusive POCSO Courts.","The total approved outlay is Rs 3,788.04 crore.","The Central share is funded from the Nirbhaya Fund."]$$::jsonb,
$$[{"question":"Which fund is named as the source of the Central share for the extended FTSC scheme?","answer":"The Nirbhaya Fund."}]$$::jsonb,
$${"title":"FTSC scheme: approval to case disposal","steps":["A sexual-offence case enters the justice system.","A dedicated FTSC provides specialised support.","Centre and States/UTs fund operational capacity.","Monitoring focuses on disposal and pendency."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-vistar-statistics-scheme$$, $$2026-11-05$$,
$$Cabinet approves VISTAR to upgrade India’s official-statistics system$$,
$$The Cabinet approved the Viksit Bharat Initiative for Statistical Transformation, Analytics & Research (VISTAR) for FY 2026-27 to FY 2030-31, with an outlay of Rs 4,371.10 crore. The central-sector scheme is intended to improve the timeliness, granularity and interoperability of official data.$$,
$$VISTAR matters for economy and governance preparation because it links MoSPI surveys, economic-census work, State statistical capacity and data-governance reform. It is not a single new index.$$,
$$The three components are Comprehensive Statistical Operations and Strengthening of Ecosystem, Support for Statistical Strengthening, and the Economic Census. MoSPI plans 59 surveys in the Sixteenth Finance Commission cycle and use of digital processes and AI/ML for data processing, validation and analysis.$$,
$$Cabinet approves Viksit Bharat Initiative for Statistical Transformation, Analytics & Research (VISTAR)$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332480$$,
$$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-11-04$$,
$$["VISTAR is approved for FY 2026-27 to FY 2030-31.","Its outlay is Rs 4,371.10 crore.","MoSPI’s statistical and data-management activities are covered.","State and UT capacity is addressed through Support for Statistical Strengthening."]$$::jsonb,
$$[{"question":"Is VISTAR merely a new economic index?","answer":"No. It is a broader central-sector scheme for official-statistics operations, State capacity and the Economic Census."}]$$::jsonb,
$${"title":"VISTAR statistical architecture","steps":["Surveys and administrative data create evidence.","Digital collection and validation improve quality.","Harmonised datasets support analysis and sharing.","Granular evidence informs policy design."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-critical-mineral-processing-capex$$, $$2026-11-05$$,
$$Cabinet clears capital support for domestic lithium and nickel processing$$,
$$The Cabinet approved a Rs 2,814 crore, five-year Capex Support Scheme to promote domestic processing of critical minerals. It targets lithium and nickel ores or intermediates to make high-purity compounds, with cobalt expected as a nickel-processing by-product.$$,
$$This is an economy, science and energy-security update. It distinguishes mining, beneficiation and processing, and connects critical-mineral value chains with batteries, electronics, defence and clean-energy technologies.$$,
$$The scheme period is FY 2026-27 to FY 2030-31. It envisages two lithium and two nickel processing plants, with a 30% capital subsidy of eligible investment. Selection begins with technical qualification and then financial bidding; approval does not mean plants are already operating.$$,
$$Cabinet Approves Capex Support Scheme to Promote Critical Mineral Processing$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332476$$,
$$Ministry of Mines / Press Information Bureau$$, $$2026-11-04$$,
$$["The outlay is Rs 2,814 crore over five years.","The scheme targets lithium and nickel processing.","Cobalt may be recovered from nickel processing.","The announced capital subsidy is 30% of eligible investment."]$$::jsonb,
$$[{"question":"Does this scheme fund only extraction of critical minerals?","answer":"No. It supports domestic processing of lithium and nickel ores or intermediates into high-purity compounds."}]$$::jsonb,
$${"title":"Critical-mineral value addition","steps":["Ore or intermediates are sourced.","Domestic facilities process high-purity compounds.","Manufacturers use the processed inputs.","Value addition and supply-chain resilience increase."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-grid-scale-storage-vgf$$, $$2026-11-05$$,
$$Cabinet approves VGF scheme for 92 GWh of grid-scale energy storage$$,
$$The Cabinet approved a Viability Gap Funding scheme with Rs 14,500 crore of support for 92 GWh of new grid-scale energy-storage capacity over FY 2026-27 to FY 2030-31. The planned mix is 60 GWh of pumped storage, 30 GWh of battery storage and 2 GWh of alternative storage technologies.$$,
$$This power-sector update illustrates why renewable-energy expansion requires balancing resources, and why storage capacity is measured in energy units such as GWh rather than only generating capacity in GW.$$,
$$VGF is public financial support intended to improve the commercial feasibility of useful infrastructure. Capacity will be allocated through tariff-based competitive bidding. The release specifies a 40% minimum domestic-content requirement for BESS projects; approval is not evidence that all capacity is commissioned.$$,
$$Cabinet approves Viability Gap Funding Scheme for development of 92 GWh Grid-Scale Energy Storage Systems$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332474$$,
$$Ministry of Power / Press Information Bureau$$, $$2026-11-04$$,
$$["The scheme provides Rs 14,500 crore of VGF support.","It targets 92 GWh of as-yet-uncommissioned storage.","The mix is 60 GWh PSP, 30 GWh BESS and 2 GWh alternative technologies.","BESS projects carry a 40% minimum domestic-content requirement."]$$::jsonb,
$$[{"question":"What does GWh measure in the storage announcement?","answer":"Energy-storage capacity: the electrical energy a system can store or deliver, not merely its instantaneous power rating."}]$$::jsonb,
$${"title":"How grid storage supports renewables","steps":["Variable renewables produce at changing times.","Storage charges when electricity is available.","It discharges at high demand or lower output.","The grid gains flexibility and reliability."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-agniveer-absorption-pathway$$, $$2026-11-05$$,
$$Cabinet adds a two-year engagement route for remaining Agniveers$$,
$$The Cabinet approved a further two-year engagement period for willing Agniveers not selected for regular employment after the first four years. The existing merit-based offer of regular employment for 25% continues; after the additional period, willing candidates meeting selection criteria will be offered regular enrolment.$$,
$$This is a major defence-governance update. Retain the sequence: regular employment for 25% remains merit-based, and the later route for the remaining group is conditional rather than automatic.$$,
$$The Agnipath scheme continues. The second engagement period comes with higher remuneration, an enhanced Seva Nidhi package and seniority benefits. It applies to remaining willing Agniveers, while later regular enrolment still requires willingness and selection criteria.$$,
$$Cabinet creates a pathway for all Agniveers to be absorbed in Defence Forces$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332524$$,
$$Ministry of Defence / Press Information Bureau$$, $$2026-11-04$$,
$$["The pre-existing merit-based regular-employment offer is for 25% of Agniveers.","The remaining 75% may take a further two-year engagement period if willing.","Regular enrolment remains subject to willingness and selection criteria.","The release says the Agnipath scheme will continue."]$$::jsonb,
$$[{"question":"Does every Agniveer become a regular soldier immediately after four years?","answer":"No. The release retains merit-based selection for 25% and creates a conditional additional two-year route for the remaining willing Agniveers."}]$$::jsonb,
$${"title":"Agniveer engagement pathway","steps":["Initial engagement is completed.","Merit-based regular employment is offered to 25%.","Others may take a two-year extension.","Later enrolment depends on willingness and criteria."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-trai-interconnection-amendment$$, $$2026-11-05$$,
$$TRAI shifts telecom-interconnection framework toward service-area and IP-based links$$,
$$TRAI released the Telecommunication Interconnection (Third Amendment) Regulations, 2026, effective 1 January 2027. The changes provide for interconnection at the Licensed Service Area level and require new interconnections to be IP-based.$$,
$$It is a useful regulator-and-infrastructure item: it tests TRAI’s statutory role and the technical idea of interconnection, which lets customers of different telecom networks communicate.$$,
$$Existing traffic at older SDCA and LDCA points of interconnection is to migrate to Licensed Service Area points over three years. Existing E1/TDM points are also to move to IP-based interconnection in phases. A POI is where networks hand traffic to each other, not a consumer service centre.$$,
$$TRAI releases The Telecommunication Interconnection (Third Amendment) Regulations, 2026$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2331941$$,
$$Telecom Regulatory Authority of India / Press Information Bureau$$, $$2026-11-03$$,
$$["The regulations take effect on 1 January 2027.","TRAI’s interconnection power is under section 11(1)(b) of the TRAI Act, 1997.","New interconnections after commencement must be IP-based.","Older arrangements migrate in phases over three years."]$$::jsonb,
$$[{"question":"What does telecom interconnection enable?","answer":"It enables traffic to pass between networks so users of different service providers can communicate."}]$$::jsonb,
$${"title":"Telecom interconnection migration","steps":["Networks agree how to hand traffic to each other.","LSA POIs replace older charging-area arrangements.","New links use IP-based interconnection.","Phased migration modernises network management."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-asi-2024-25-publications$$, $$2026-11-05$$,
$$MoSPI releases detailed ASI 2024-25 factory-sector publications$$,
$$MoSPI released Annual Survey of Industries 2024-25 Volume I, Summary Results of the Factory Sector, unit-level data and metadata. The release reports 9.28% year-on-year GVA growth for the manufacturing corporate sector.$$,
$$This is a core official-statistics update. It helps distinguish ASI from household surveys and understand how factory-sector data feed National Accounts Statistics at national and State levels.$$,
$$ASI studies the structure and growth of registered manufacturing through output, value added, employment and capital formation. Detailed results use NIC 2008: all-India results reach 2-, 3- and 4-digit levels, while State/UT results are provided at 2- and 3-digit levels.$$,
$$Publications of Annual Survey of Industries 2024-25$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332475$$,
$$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-11-04$$,
$$["ASI 2024-25 covers registered manufacturing-sector information.","Reported manufacturing-corporate-sector GVA growth was 9.28% year on year.","The release includes Volume I, summary results, unit-level data and metadata.","ASI results support National Accounts Statistics at national and State levels."]$$::jsonb,
$$[{"question":"Does ASI primarily describe household consumption or the registered factory sector?","answer":"The registered factory sector; it provides information on manufacturing output, value added, employment, capital and related measures."}]$$::jsonb,
$${"title":"ASI data to economic measurement","steps":["Registered factories report data.","ASI compiles sector and State measures.","NIC classifies industrial activity.","Results inform industrial analysis and national accounts."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-05-ndc-tia-road-freight$$, $$2026-11-05$$,
$$NITI Aayog and GIZ sign road-freight decarbonisation implementation agreement$$,
$$NITI Aayog and GIZ signed an implementation agreement under Phase II of the Nationally Determined Contribution–Transport Initiative for Asia on 3 November. The collaboration is intended to accelerate decarbonisation of India’s road-freight sector.$$,
$$This climate-governance and transport-policy update connects Nationally Determined Contributions with the challenge of lowering emissions from medium- and heavy-duty freight vehicles.$$,
$$NDC-TIA II is a regional initiative supported by the German Government’s International Climate Initiative. The release names WRI India, ICCT India and Agora Energiewende among implementing partners. The agreement formalises cooperation; it does not establish a mandatory vehicle standard or prove a nationwide fleet conversion.$$,
$$NITI Aayog and GIZ India Sign Implementation Agreement under NDC-TIA II$$,
$$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2332576$$,
$$NITI Aayog / Press Information Bureau$$, $$2026-11-04$$,
$$["The agreement was signed on 3 November 2026.","It is under NDC–Transport Initiative for Asia Phase II.","NDC-TIA II is supported by Germany’s International Climate Initiative.","The collaboration focuses on decarbonising India’s road freight."]$$::jsonb,
$$[{"question":"Why is road-freight decarbonisation more than simply buying electric trucks?","answer":"It also needs charging infrastructure, financing mechanisms and an enabling regulatory framework."}]$$::jsonb,
$${"title":"Road-freight decarbonisation","steps":["Freight vehicles create transport emissions.","Technology, charging and finance affect adoption.","Institutions coordinate support and evidence.","Lower-carbon freight contributes to climate goals."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-05-ftsc-continuation$$,
$$2026-11-05-vistar-statistics-scheme$$,
$$2026-11-05-critical-mineral-processing-capex$$,
$$2026-11-05-grid-scale-storage-vgf$$,
$$2026-11-05-agniveer-absorption-pathway$$,
$$2026-11-05-trai-interconnection-amendment$$,
$$2026-11-05-asi-2024-25-publications$$,
$$2026-11-05-ndc-tia-road-freight$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
